# Run in a new cell in the SAME Kaggle notebook kernel after the dual-VAE OOM.
# Reuses installed packages and verified model files. Restarts only our ComfyUI process.
from pathlib import Path
import json
assert all(k in globals() for k in ('ROOT','COMFY','PY','child_env','MODELS_READY','run')), 'Use the existing Kaggle notebook kernel.'
require_models_ready()
resume_id=globals().get('RESUME_CHECKPOINT','')
previous_id=globals().get('run_id','')
if not resume_id and previous_id and (COMFY/'output/h3_latents'/f'{previous_id}.safetensors').is_file():
    resume_id=previous_id
if isinstance(globals().get('entry'),dict):
    (ROOT/'pre-recovery-history.json').write_text(json.dumps(entry,indent=2))
MGPU=COMFY/'custom_nodes/ComfyUI-MultiGPU-Kaggle'
# Compatibility with current Comfy-Org per-layer .comfy_quant metadata.
compat_source='"""Read both ComfyUI quantization layouts without rewriting checkpoint weights."""\nimport json\n\n\ndef read_h3_quant_layers(weights):\n    metadata=weights.metadata() or {}\n    if \'_quantization_metadata\' in metadata:\n        layers=json.loads(metadata[\'_quantization_metadata\'])[\'layers\']\n    else:\n        layers={}\n        for name in weights.keys():\n            if name.endswith(\'.comfy_quant\'):\n                data=weights.get_tensor(name)\n                layers[name[:-len(\'.comfy_quant\')]]=json.loads(bytes(data.tolist()).decode(\'utf-8\'))\n    if not layers:\n        raise ValueError(\'Checkpoint contains neither legacy nor per-layer quantization metadata.\')\n    return layers\n\n\ndef validate_h3_quant_layers(weights):\n    layers=read_h3_quant_layers(weights)\n    for suffix in (\'attn.qkv_proj\',\'attn.out_proj\',\'mlp.fc1\',\'mlp.fc2\'):\n        name=\'blocks.0.\'+suffix\n        conf=layers.get(name,{})\n        if conf.get(\'format\')!=\'int8_tensorwise\' or not conf.get(\'convrot\'):\n            raise ValueError(f\'H3 tensor parallel requires INT8 ConvRot: {name}: {conf}\')\n    return layers\n'
(MGPU/'h3_quant_compat.py').write_text(compat_source)
tp_path=MGPU/'h3_tensor_parallel.py'
tp_source=tp_path.read_text()
old='layers = json.loads(f.metadata()["_quantization_metadata"])["layers"]'
new='layers = read_h3_quant_layers(f)'
if old in tp_source:
    assert tp_source.count(old)==1,'Unexpected TP loader source; refusing an ambiguous patch.'
    tp_source=tp_source.replace(old,new)
    tp_source=tp_source.replace('from .tp_source import open_weights',
        'from .tp_source import open_weights\nfrom .h3_quant_compat import read_h3_quant_layers')
    tp_path.write_text(tp_source)
else:
    assert new in tp_source and 'from .h3_quant_compat import read_h3_quant_layers' in tp_source,'Unexpected TP loader revision.'
print('Installed H3 quantization metadata compatibility reader.')


checkpoint_source='"""Persist sampled H3 video/audio before decoding; allow decode-only recovery."""\nfrom pathlib import Path\nimport gc\nimport re\nimport sys\nimport torch\nfrom safetensors.torch import save_file,load_file\nimport folder_paths\nimport comfy.model_management\nfrom comfy.nested_tensor import NestedTensor\n\n\ndef checkpoint_path(checkpoint_id):\n    if not re.fullmatch(r\'[A-Za-z0-9_-]{1,80}\',checkpoint_id):\n        raise ValueError(\'Checkpoint ID must contain only letters, digits, underscore or hyphen.\')\n    root=Path(folder_paths.get_output_directory())/\'h3_latents\'\n    root.mkdir(parents=True,exist_ok=True)\n    return root/(checkpoint_id+\'.safetensors\')\n\n\ndef release_sampling_memory():\n    # The fork keeps TP tensors outside ComfyUI\'s model manager, in two caches.\n    for name,module in list(sys.modules.items()):\n        if name.endswith(\'.h3_tensor_parallel\') and hasattr(module,\'_SHARD_CACHE\'):\n            module._SHARD_CACHE.clear()\n            module.release_gpu(drop_shards=True)\n            for tp in module._INSTANCES.values():\n                tp.lora={};tp.lora_sig=()\n    comfy.model_management.unload_all_models()\n    gc.collect()\n    comfy.model_management.soft_empty_cache()\n\n\ndef pack_latents(samples):\n    latent=samples[\'samples\']\n    if not latent.is_nested:raise ValueError(\'Expected H3 joint video/audio latents.\')\n    parts=latent.unbind()\n    if len(parts)!=2 or parts[0].ndim!=5 or parts[1].ndim!=4:\n        raise ValueError(\'Unexpected H3 latent layout.\')\n    tensors={name:value.detach().to(\'cpu\').contiguous() for name,value in zip((\'video\',\'audio\'),parts)}\n    if not all(torch.isfinite(t).all() for t in tensors.values()):\n        raise ValueError(\'Sampler produced non-finite latents; refusing to decode.\')\n    return tensors\n\n\nclass H3CheckpointBeforeDecode:\n    @classmethod\n    def INPUT_TYPES(cls):\n        return {\'required\':{\'samples\':(\'LATENT\',),\'checkpoint_id\':(\'STRING\',{\'default\':\'clip\'})}}\n    RETURN_TYPES=(\'LATENT\',)\n    FUNCTION=\'save\'\n    CATEGORY=\'h3/recovery\'\n    def save(self,samples,checkpoint_id):\n        tensors=pack_latents(samples)\n        destination=checkpoint_path(checkpoint_id)\n        partial=destination.with_suffix(\'.partial\')\n        save_file(tensors,str(partial),metadata={\'format\':\'h3-joint-latent-v1\'})\n        partial.replace(destination)\n        release_sampling_memory()\n        return ({**samples,\'samples\':NestedTensor([tensors[\'video\'],tensors[\'audio\']])},)\n\n\nclass H3LoadDecodeCheckpoint:\n    @classmethod\n    def INPUT_TYPES(cls):\n        return {\'required\':{\'checkpoint_id\':(\'STRING\',{\'default\':\'clip\'})}}\n    @classmethod\n    def VALIDATE_INPUTS(cls,checkpoint_id):\n        try:return True if checkpoint_path(checkpoint_id).is_file() else \'Saved latent checkpoint does not exist.\'\n        except ValueError as error:return str(error)\n    RETURN_TYPES=(\'LATENT\',)\n    FUNCTION=\'load\'\n    CATEGORY=\'h3/recovery\'\n    def load(self,checkpoint_id):\n        tensors=load_file(str(checkpoint_path(checkpoint_id)),device=\'cpu\')\n        samples={\'samples\':NestedTensor([tensors[\'video\'],tensors[\'audio\']])}\n        pack_latents(samples)\n        release_sampling_memory()\n        return (samples,)\n\n\nNODE_CLASS_MAPPINGS={\'H3CheckpointBeforeDecode\':H3CheckpointBeforeDecode,\n                     \'H3LoadDecodeCheckpoint\':H3LoadDecodeCheckpoint}\n'
checkpoint_plugin=COMFY/'custom_nodes/H3CheckpointRecovery'
checkpoint_plugin.mkdir(parents=True,exist_ok=True)
(checkpoint_plugin/'__init__.py').write_text(checkpoint_source)

if 'server' in globals() and server.poll() is None:
    server.terminate()
    try:server.wait(timeout=15)
    except __import__('subprocess').TimeoutExpired:
        server.kill();server.wait(timeout=15)
if 'log' in globals() and not log.closed:log.close()
DUAL_VAE=False
BENCHMARK_RUNS=1
RESUME_CHECKPOINT=resume_id
RUN_GENERATION=True
print('Decode-only recovery:',resume_id) if resume_id else print('One full render will run; latents will be saved before decoding.')

